import { createServer } from 'node:http';
import { readFileSync, writeFileSync, mkdirSync, renameSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = fileURLToPath(new URL('.', import.meta.url));

export function createTodoServer({ dataFile = resolve(root, 'data/todos.json') } = {}) {
  let todos;
  try {
    todos = JSON.parse(readFileSync(dataFile, 'utf8'));
    if (!Array.isArray(todos)) throw new Error('待办数据必须为数组');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    todos = [];
  }
  function save(next) {
    mkdirSync(dirname(dataFile), { recursive: true });
    writeFileSync(`${dataFile}.tmp`, JSON.stringify(next, null, 2) + '\n');
    renameSync(`${dataFile}.tmp`, dataFile);
    todos = next;
  }
  return createServer(async (request, response) => {
    function json(status, value) {
      response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
      response.end(JSON.stringify(value));
    }
    try {
      const pathname = new URL(request.url, 'http://localhost').pathname;
      if (request.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
        const html = readFileSync(resolve(root, 'index.html'));
        response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
        response.end(html);
        return;
      }
      if (pathname === '/api/todos' && request.method === 'GET') return json(200, todos);
      const update = pathname.match(/^\/api\/todos\/([^/]+)$/);
      if ((pathname === '/api/todos' && request.method === 'POST') || (update && request.method === 'PATCH')) {
        let body = '';
        request.setEncoding('utf8');
        for await (const chunk of request) {
          body += chunk;
          if (body.length > 16384) return json(413, { error: '请求过大' });
        }
        let value;
        try { value = JSON.parse(body); } catch { return json(400, { error: 'JSON 格式错误' }); }
        if (request.method === 'POST') {
          if (typeof value?.text !== 'string' || !value.text.trim() || value.text.trim().length > 500) {
            return json(400, { error: '请输入 1 至 500 字的事项' });
          }
          const todo = { id: randomUUID(), text: value.text.trim(), completed: false };
          save([...todos, todo]);
          return json(201, todo);
        }
        if (typeof value?.completed !== 'boolean') return json(400, { error: '完成状态必须是布尔值' });
        const todo = todos.find(item => item.id === update[1]);
        if (!todo) return json(404, { error: '事项不存在' });
        const changed = { ...todo, completed: value.completed };
        save(todos.map(item => item.id === todo.id ? changed : item));
        return json(200, changed);
      }
      json(404, { error: '未找到' });
    } catch (error) {
      console.error(error);
      json(500, { error: '操作失败，请重试' });
    }
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const server = createTodoServer({ dataFile: process.env.TODO_DATA_FILE || resolve(root, 'data/todos.json') });
  server.listen(Number(process.env.PORT || 3000), process.env.HOST || '127.0.0.1', () => {
    console.log(`todo 已启动，端口 ${server.address().port}`);
  });
}
