import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';

test('CLI 精确输出', () => {
  assert.equal(execFileSync(process.execPath, ['greet.mjs', '张三'], { encoding: 'utf8' }).trimEnd(), '您好，张三！');
});

test('API 添加、完成、JSON 持久化和重新加载', async () => {
  const { createTodoServer } = await import('./server.mjs');
  const directory = await mkdtemp(join(process.cwd(), '.todo-test-'));
  const dataFile = join(directory, 'todos.json');
  let server;
  async function start() {
    server = createTodoServer({ dataFile });
    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
    return `http://127.0.0.1:${server.address().port}/api/todos`;
  }
  async function stop() {
    await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  }
  try {
    let url = await start();
    assert.deepEqual(await (await fetch(url)).json(), []);
    const invalid = await fetch(url, { method: 'POST', body: JSON.stringify({ text: ' ' }) });
    assert.equal(invalid.status, 400);
    const response = await fetch(url, { method: 'POST', body: JSON.stringify({ text: '验收事项' }) });
    assert.equal(response.status, 201);
    const todo = await response.json();
    assert.equal(todo.text, '验收事项');
    assert.equal(todo.completed, false);
    const updated = await fetch(`${url}/${todo.id}`, { method: 'PATCH', body: JSON.stringify({ completed: true }) });
    assert.equal(updated.status, 200);
    const completed = await updated.json();
    assert.deepEqual(completed, { ...todo, completed: true });
    assert.deepEqual(JSON.parse(await readFile(dataFile, 'utf8')), [completed]);
    await stop();
    url = await start();
    assert.deepEqual(await (await fetch(url)).json(), [completed]);
    const html = await (await fetch(url.replace('api/todos', ''))).text();
    assert.match(html, /id="todoInput"/);
    assert.match(html, /id="add"/);
    assert.match(html, /id="list"/);
    assert.match(html, /fetch\('api\/todos'/);
    assert.match(html, /已完成/);
    assert.doesNotMatch(html, /localStorage/);
  } finally {
    if (server?.listening) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
# greeting 与 todo

需要 Node.js 22 或更新版本，无第三方依赖。

问候：`node greet.mjs 张三`，输出 `您好，张三！`。

网页：`node server.mjs`，打开 `http://127.0.0.1:3000`。可通过 `HOST`、`PORT` 设置监听地址和端口。添加事项后勾选完成，刷新保留事项与状态。

数据默认保存在 `data/todos.json`；可用 `TODO_DATA_FILE` 指定另一文件。仅支持单服务进程，无账号隔离。损坏的数据文件会阻止启动，避免覆盖已有数据。

验收：`node --test`、`node --check server.mjs`、`node --check greet.mjs`。测试使用工作目录内的临时数据文件并自动清理，不修改实际待办。
