<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>todo · 待办</title>
  <style>
    body { font: 17px/1.6 system-ui, sans-serif; color: #24342d; background: #f5f7f3; margin: 0; }
    main { max-width: 560px; margin: 10vh auto; padding: 28px; }
