  <script type="module">
    const input = document.querySelector('#todoInput');
    const add = document.querySelector('#add');
    const list = document.querySelector('#list');
    const status = document.querySelector('#status');
    async function api(url, options) {
      const response = await fetch(url, options);
      const value = await response.json();
      if (!response.ok) throw new Error(value.error || '操作失败');
      return value;
    }
    function render(todos) {
      list.replaceChildren();
      for (const todo of todos) {
        const item = document.createElement('li');
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = todo.completed;
        const text = document.createElement('span');
        text.textContent = todo.text + (todo.completed ? ' · 已完成' : '');
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          try {
            const updated = await api('api/todos/' + todo.id, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked })
            });
            todo.completed = updated.completed;
            text.textContent = todo.text + (todo.completed ? ' · 已完成' : '');
            status.textContent = '已保存';
          } catch (error) {
            checkbox.checked = todo.completed;
            status.textContent = error.message;
          } finally { checkbox.disabled = false; }
        });
        label.append(checkbox, text);
        item.append(label);
        list.append(item);
      }
    }
    async function load() {
      const response = await fetch('api/todos');
      if (!response.ok) throw new Error('读取失败，请刷新重试');
      render(await response.json());
    }
    document.querySelector('#todoForm').addEventListener('submit', async event => {
      event.preventDefault();
      if (!input.value.trim()) return;
      add.disabled = true;
      try {
        await api('api/todos', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: input.value }) });
        input.value = '';
        await load();
        status.textContent = '已保存';
      } catch (error) { status.textContent = error.message; }
      finally { add.disabled = false; }
    });
    load().catch(error => { status.textContent = error.message; });
  </script>
</body>
</html>
